+// reviewVerdictQualifiers mark an approve that still carries feedback or a
+// condition, so it must be posted rather than treated as clean.
+var reviewVerdictQualifiers = map[string]bool{
+	"nit": true, "nits": true, "but": true, "however": true,
+	"once": true, "after": true, "pending": true, "unless": true,
+}
+
+// isCleanReviewVerdict reports whether every reviewer approved without
+// qualification. Combined narratives put each reviewer under a "## <name>"
+// heading, so one approving reviewer must not hide another's findings.
+func isCleanReviewVerdict(verdict string) bool {
+	sections := splitReviewerSections(verdict)
+	if len(sections) == 0 {
+		return false
+	}
+	for _, lines := range sections {
+		if !isCleanReviewerSection(lines) {
+			return false
+		}
+	}
+	return true
+}
+
+// splitReviewerSections groups non-empty lines by "## <name>" headings. A
+// heading that is itself a verdict, such as "## approve", stays a line.
+func splitReviewerSections(verdict string) [][]string {
+	var sections [][]string
+	var current []string
+	for _, raw := range strings.Split(verdict, "\n") {
+		line := strings.TrimSpace(raw)
+		if line == "" {
+			continue
+		}
+		if _, isVerdict := parseReviewVerdictLine(line); strings.HasPrefix(line, "## ") && !isVerdict {
+			if len(current) > 0 {
+				sections = append(sections, current)
+			}
+			current = nil
+			continue
+		}
+		current = append(current, line)
+	}
+	if len(current) > 0 {
+		sections = append(sections, current)
+	}
+	return sections
+}
+
+// isCleanReviewerSection requires the section to end in a clean approve and to
+// contain no other verdict. Prompts put the verdict first, so a trailing
+// approve cannot override an earlier request for changes.
+func isCleanReviewerSection(lines []string) bool {
+	for _, line := range lines {
+		if clean, isVerdict := parseReviewVerdictLine(line); isVerdict && !clean {
+			return false
+		}
+	}
+	clean, isVerdict := parseReviewVerdictLine(lines[len(lines)-1])
+	return isVerdict && clean
+}
+
+func parseReviewVerdictLine(line string) (clean, isVerdict bool) {
+	line = strings.ToLower(strings.TrimSpace(line))
+	line = strings.TrimSpace(strings.TrimLeft(line, "#>"))
+	line = strings.TrimLeft(line, "*_`")
+	if strings.HasPrefix(line, "request changes") {
+		return false, true
+	}
+	rest, ok := strings.CutPrefix(line, "approve")
+	if !ok {
+		return false, false
+	}
+	if rest != "" {
+		first, _ := utf8.DecodeRuneInString(rest)
+		if !unicode.IsSpace(first) && !unicode.IsPunct(first) && !unicode.IsSymbol(first) {
+			return false, false
+		}
+	}
+	words := strings.FieldsFunc(rest, func(r rune) bool { return !unicode.IsLetter(r) })
+	for _, word := range words {
+		if reviewVerdictQualifiers[word] {
+			return false, true
+		}
+	}
+	return true, true
+}
